package dev.thefoolish.generated.anishelf;import android.content.*;import java.util.*;public final class LocalStore{private final SharedPreferences p;LocalStore(Context c){p=c.getSharedPreferences("anishelf_state",0);}boolean flag(String k){return p.getBoolean(k,false);}void flag(String k,boolean v){p.edit().putBoolean(k,v).apply();}int number(String k){return p.getInt(k,0);}void number(String k,int v){p.edit().putInt(k,Math.max(0,v)).apply();}String text(String k,String d){return p.getString(k,d);}void putText(String k,String v){p.edit().putString(k,v==null?"":v).apply();}Set<String> set(String k){return new LinkedHashSet<>(p.getStringSet(k,new LinkedHashSet<>()));}void set(String k,Set<String> v){p.edit().putStringSet(k,new LinkedHashSet<>(v)).apply();}}
